const calculateTimeUsed = (startTime, endTime) => {
    const start = moment__WEBPACK_IMPORTED_MODULE_1___default()(startTime);
    const end = moment__WEBPACK_IMPORTED_MODULE_1___default()(endTime);
    const h = end.diff(start, "hours");
    const m = end.diff(start, "minutes");
    const d = end.diff(start, "days");
    const s = end.diff(start, "seconds");
    if (d > 0) {
        return `${d} days~ ${h} hours ~ ${m} mins`;
    }
    else if (h > 0) {
        return `${h} hours ~ ${m} mins`;
    }
    else if (m > 0) {
        return `${m} mins`;
    }
    else {
        return `${s} seconds`;
    }
};
